import fs from 'node:fs';
export const gameCSS=fs.readFileSync(new URL('home-expanded-game.css',import.meta.url),'utf8')+'\n'+fs.readFileSync(new URL('mining-raids-game.css',import.meta.url),'utf8');
export const sampleOffers=[
  {id:'fixture-short-A',kind:'short',name:'Rövid út',energy:9,xp:'448k',nyang:'90k'},
  {id:'fixture-medium-A',kind:'medium',name:'Közepes út',energy:15,xp:'746,8k',nyang:'150k'},
  {id:'fixture-long-A',kind:'long',name:'Hosszú út',energy:36,xp:'1,9kk',nyang:'373,4k'}
];
export const apiSample=()=>({expedition:{offers:sampleOffers.map((o,i)=>({id:o.id,travelMin:[11,23,90][i],pace:1,energyCost:o.energy,preview:{xp:[448051,746899,1930111][i],nyang:[90021,150099,373499][i]}}))},mods:{xpMult:1,nyangMult:1,xpPaid:0,nyangPaid:0,travelMult:1},derived:{xpBonus:0,nyangBonus:0}});
// Deliberately no duration on the user's three numerical samples: none supplied.
// Timed cases explicitly add their own duration independently in tests.
const script=String.raw`
window.gameWrites=[];window.tabClicks=[];window.renderCount=0;
window.miningNames={mine:'Tárna',smelt:'Olvasztó',craft:'Műhely',master:'Gwangsu'};
window.miningBody={
 mine:'<h3 class="mine-h3">Vasérc kitermelése</h3><p class="mine-lead">Aktív bányászat · Sárkány-hegy</p><dl class="mine-facts"><dt>Kitermelt érc</dt><dd>125</dd><dt>Hátralévő idő</dt><dd data-timer>02:14:35</dd></dl><button data-resource="collect">Begyűjtés</button>',
 smelt:'<h3 class="mine-h3">Olvasztó</h3><p class="mine-lead">A megfigyelt raktárból készíthető fémrudak.</p>'+['Vasrúd','Rézrúd','Ezüstrúd','Aranyrúd','Kristályrúd','Mithrilrúd'].map((n,i)=>'<div class="mine-card" data-smelt="'+i+'"><div class="mine-card__name">'+n+'</div><p class="mine-card__meta">Érc: '+(120-i*10)+' · 10 érc / rúd</p><input type="number" value="1"><button data-resource="smelt">Olvasztás</button></div>').join(''),
 craft:'<h3 class="mine-h3">Csákány fejlesztése</h3><div class="mine-card" data-craft="pick"><h4>Acélcsákány · 4. fok</h4><p>Ütésidő: 18 mp</p><p>Következő szint: 5. fok</p><button data-resource="upgrade">Fejlesztés</button></div><h3 class="mine-h3">Berendezés és patina</h3><p>Megfigyelt receptek · 3 elérhető fejlesztés</p>',
 master:'<h3 class="mine-h3">Gwangsu mester</h3><p>Szerencse: 12%</p><p>Napi adomány: 2 / 5</p><p>Kvarc: 24</p><button data-resource="donate">Adomány</button><button data-resource="luck">Szerencse növelése</button>'
};
window.miningKey='mine';
window.renderMining=function(key){
 miningKey=key;renderCount++;
 document.querySelectorAll('[data-mine-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.mineTab===key)));
 const body=document.querySelector('.mine-window__body');body.setAttribute('aria-labelledby','mining-tab-'+key);body.innerHTML='<div class="mine-pane">'+miningBody[key]+'</div><p class="mine-result" role="status"></p>';
};
window.bindMining=function(){document.querySelectorAll('[data-mine-tab]').forEach(b=>b.onclick=()=>{tabClicks.push(b.dataset.mineTab);renderMining(b.dataset.mineTab);});renderMining(miningKey);};
window.replaceMining=function(){const n=document.querySelector('.mine-window');const next=n.cloneNode(true);next.querySelectorAll('[data-ssa-mining-owned]').forEach(x=>x.remove());n.replaceWith(next);bindMining();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-resource],[data-start-raid]');if(b)gameWrites.push(b.dataset.resource||'start-raid');});
window.renderRaids=function(offers){document.querySelector('#raid-list').innerHTML=offers.map(o=>'<li class="expo-offer expo-offer--'+o.kind+'" data-offer="'+o.id+'" data-minutes="999"><header class="expo-offer__head"><span class="expo-len">'+o.name+'</span><h3>Hegyi ösvény · 120. szint</h3></header><div class="expo-offer__facts"><div class="expo-offer__fact"><s class="expo-offer__was" aria-hidden="true">999 perc</s><span class="expo-offer__time">'+(o.time||'Idő nem szerepel a mintában')+'</span></div><div class="expo-offer__fact"><img class="expo-offer__energy" alt="" src="/fixture/energy.svg">'+o.energy+' energia</div></div><div class="expo-offer__reward">'+(o.xp===null?'':'<span>'+o.xp+' XP</span>')+'<span><svg class="expo-offer__coin" aria-hidden="true" viewBox="0 0 12 12"><circle cx="6" cy="6" r="5" fill="#edc66d"/></svg><span class="visually-hidden">Nyang: </span>'+o.nyang+'</span><span><img class="expo-offer__mat" alt="" src="/fixture/energy.svg">Anyagesély: 21%</span></div><button class="expo-offer__go" data-start-raid>Indulás</button></li>').join('');};
bindMining();renderRaids(window.sampleOffers);
`;
export const fixtureHTML=`<!doctype html><html lang="hu"><head><meta charset="utf-8"><title>Tárnák és Portya – helyi próba</title><link rel="stylesheet" href="/fixture/game.css"><style>
html,body{height:100%;margin:0;overflow:hidden}.game-stage{position:relative;height:100vh;--hud-h:82px;--rail-w:94px;--gutter:16px;background:#151a1e}.fixture-hud{position:absolute;top:0;left:0;right:0;height:68px;background:#1a1815f5;border-bottom:1px solid #967b46;display:flex;align-items:center;gap:32px;padding:0 24px;color:#e8d5a8;z-index:10}.fixture-rail{position:absolute;left:12px;top:96px;width:66px;display:grid;gap:12px;z-index:10}.fixture-rail button{padding:9px 3px;color:#ead7a7;background:#2c261d;border:1px solid #806844}.fixture-caption{position:absolute;bottom:3px;left:105px;color:#ffe1a0;font:11px system-ui;z-index:2}.fixture-scene{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.7}.mine-window{min-height:0}.mine-window__body{overflow:auto}.fixture-raid-view{position:absolute;inset:95px 30px 35px 110px;overflow:auto}.fixture-raid-view h1{font-size:24px}.fixture-raid-view ul{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;list-style:none;padding:0;max-width:1130px}.fixture-raid-view .expo-offer__energy{width:18px}.fixture-raid-view .expo-offer__reward{display:flex;gap:12px;flex-wrap:wrap}.fixture-raid-view .expo-offer__coin,.fixture-raid-view .expo-offer__mat{width:18px;height:18px}.fixture-raid-view .expo-offer{padding:18px;background:#201d18f5}.fixture-raid-view button{padding:9px}.fixture-raid-view .expo-offer__fact{display:flex;gap:8px;align-items:center}.fixture-raid-view .expo-offer__was{display:none}@media(max-width:850px){.fixture-rail{width:50px;left:4px}.game-stage{--rail-w:65px}.fixture-caption{left:70px}.fixture-raid-view{left:70px;right:12px}.fixture-raid-view ul{grid-template-columns:1fr}.fixture-hud{gap:15px;font-size:12px}}
</style></head><body><main class="game-stage"><div class="hud fixture-hud"><b>STONESTORM</b><span>♥ 18 200 / 18 200</span><span>⚡ 120 energia</span><span>Helyi tesztminta</span></div><nav class="fixture-rail"><button>Tárnák</button><button>Portya</button><button>Otthon</button><button>Karakter</button></nav><div class="mine-stage"><div class="stage-scene mine-scene"><img class="fixture-scene" src="/fixture/mine.webp" alt=""></div><div class="stage-safe mine-safe"><section class="stage-window mine-window" aria-labelledby="mining-title"><h2 id="mining-title" class="stage-window__title title-plaque one-line">Tárnák</h2><div class="tabs mine-tabs" role="tablist">${[['mine','Tárna'],['smelt','Olvasztó'],['craft','Műhely'],['master','Gwangsu']].map(([k,n])=>`<button id="mining-tab-${k}" data-mine-tab="${k}" role="tab" class="tabs__tab" aria-controls="mining-pane" aria-selected="${k==='mine'}">${n}</button>`).join('')}</div><div><div class="mine-stock">Raktár · Vasérc 125 · Rézérc 84 · Nyang 1,2kk</div></div><div id="mining-pane" class="stage-window__body mine-window__body" role="tabpanel" aria-labelledby="mining-tab-mine"></div></section></div></div><section class="fixture-raid-view" hidden><h1>Portyák</h1><p>Reprodukálható helyi minta · a megadott három ajánlat</p><ul id="raid-list"></ul></section><small class="fixture-caption">Nyilvános DOM/CSS alapján készített helyi tesztfelület · mintaadatok · nincs élő játékművelet</small></main><script>window.sampleOffers=${JSON.stringify(sampleOffers)};${script}</script></body></html>`;
